SourceCode.Declaration:
/// <summary>
/// The result of claimJournal/heartbeatClaim/releaseJournal. On a refused claim, Success is
/// false, ErrorCode says why (CLAIMED_BY_OTHER, CLAIM_EXPIRED, CLAIM_LOST, JOURNAL_POSTED,
/// JOURNAL_NOT_FOUND, NOT_IMPLEMENTED) and ClaimedBy names the current holder where there is one.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountClaimResponse
{
    boolean     success;
    str         errorCode;
    str         message;
    str         claimToken;
    str         claimedBy;
    str         rangeId;
    str         locationFrom;
    str         locationTo;
    utcdatetime expiresUtc;
    int         heartbeatSeconds;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

