}

[DataMemberAttribute('ExpiresUtc')]
public utcdatetime parmExpiresUtc(utcdatetime _value = expiresUtc)
{
    expiresUtc = _value;
    return expiresUtc;
}

[DataMemberAttribute('HeartbeatSeconds')]
public int parmHeartbeatSeconds(int _value = heartbeatSeconds)
{
    heartbeatSeconds = _value;
    return heartbeatSeconds;
}
